const STATIC_DICTIONARY_EN = Object.keys(STRINGS.bn).reduce((map, key) => {
  const source = STRINGS.bn[key];
  const translated = STRINGS.en[key];
  if (typeof source === 'string' && typeof translated === 'string' && !Object.prototype.hasOwnProperty.call(map, source)) {
    map[source] = translated;
  }
  return map;
}, {});

